"""Complete four narrowly focused follow-ups and three synthesis steps under USD30.

Original high-effort attempts are preserved and charged. No blind retries: every
follow-up has a new explicit narrower task. Use enough output room for completion.
"""
import concurrent.futures,json,time
import fable_deep_review as D

def follow(name,title,task):
    original=D.CACHE/(name+'.request.json');response=D.CACHE/(name+'.response.json')
    deadline=time.monotonic()+1200
    while not response.exists():
        if time.monotonic()>deadline:raise RuntimeError('Original response not completed; no retry')
        time.sleep(3)
    r=json.loads(response.read_text(encoding='utf8'))
    if r.get('stop_reason')=='end_turn':return D.txt(r)
    content=json.loads(original.read_text(encoding='utf8'))['messages'][0]['content']
    # Replace the oversized request with one narrower task and the same public sources.
    content=content[:-1]+[D.textblock('''The previous request reached its output limit before a usable final answer. This is a NEW NARROWER source-audit task, not a request to reproduce the previous reasoning. Read the supplied source material but deliver a COMPLETE concise evidence report. Do not output private reasoning. Unknowns may remain unknown. English1500words maximum. Give exact PDF-page and code-function locators for the claims that matter; do not enumerate every benchmark. Finish the requested artifact before exploring side issues. Preserve source facts versus your application inference.\nFOCUS:\n'''+task+'\nPREVIOUS VISIBLE PARTIAL (unverified, not authoritative):\n'+D.txt(r))]
    return D.call(title,content,max_tokens=49152,effort='medium')

def main():
    tasks={
     '01_closest_fusion_fulltext':('05_completed_fusion_evidence','For each of RTCAKENN, COMPASS and Diag2Diag fill exactly8 fields: input and target, whether current/previous target diagnostic is input, actual split unit and temporal order, direct high-rate validation evidence, handling missing/stale sensors, computation vs actual deployment, closest overlap with CES nowcast, one material uncertainty. Correct old claims about absence of discharge holdout and absence of deployed diagnostic-gap inference. Then give3 task-specific hypotheses that remain testable with our actual data. Avoid an exhaustive literature narrative.'),
     '02_filter_code_fulltext':('06_completed_filter_evidence','Compare only RKN,CRU,KalmanNet information sets and source-code update/mask contracts. Known f/h requirement applies to original KalmanNet, not RKN/CRU. Identify filter vs smoother and pseudo-observation vs a genuinely newly arrived CES sample. Describe one smallest learned-latent candidate and one simple source-time-consistent comparator; explain what remains different from the existing hand-coded observer and anchor concatenation without claiming novelty. Give2 competing explanations and one falsifier each. Cite at most6 exact source-code functions or paper-page locators.'),
     '03_report_target_likelihood':('07_completed_target_evidence','Focus on what faithful heteroscedastic and betaNLL actually change about mean/variance gradients and report-level evaluation. Distinguish standard Gaussian NLL already implemented but not scientifically screened from a new faithfully trained comparison. What is estimable for F/L5, what needs independent noise/physics truth, and what minimal matched-input experiment distinguishes mean-training pathology from target/support differences? Specify paired estimands, no separate-CI overlap tests, no non-significance-as-equivalence. Cite3-5 exact locators and finish.'),
     '04_representation_distillation':('08_completed_representation_evidence','Focus on two implementable hypotheses: causal representation pretraining versus random initialization, and TRAIN-only future-information teacher versus no-teacher/matched-compute controls. Clearly separate pretraining future context within TRAIN from TEST/online leakage. No full-rate input is technically required. What information is actually privileged in this CES data, and what would make the teacher useless? Give one bounded experiment for each with an explicit negative result. Do not turn ordinary distillation into a novelty claim. Cite3-5 exact primary locators.')}
    reports={}
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as ex:
        fs={ex.submit(follow,k,*v):k for k,v in tasks.items()}
        for f in concurrent.futures.as_completed(fs):reports[fs[f]]=f.result()
    r,b=D.E.gate();assert r;p=D.E.packet(r,b)
    evidence={'context':p['context'],'paired':p['b94']['paired_by_design'],'budgets':p['b94']['budget_summary'],'latency':p['b94']['latency'],'internal_val':p['b98']}
    D.save(D.OUT/'evidence_binding.json',b)
    crosswalk=(D.OUT/'EXISTING_WORK.md').read_text(encoding='utf8')
    checks=(D.OUT/'PRIMARY_CHECKS.md').read_text(encoding='utf8')
    research=D.call('09_substantive_research_programs',[D.textblock(D.CONTEXT),D.textblock('PRIMARY SOURCE DOSSIERS\n'+json.dumps(reports)),D.textblock('SOURCE-CHECKED EXISTING WORK\n'+crosswalk+'\nHOST CHECKS\n'+checks),D.textblock('AUDITED ANONYMOUS CURRENT RESULTS\n'+json.dumps(evidence)),D.textblock('''English<=2400words. Build4 substantive alternative research programs, not just an artifact inventory: an explicit source-time/arrival-event learned filter or anchor residual estimator; causal representation or privileged teacher; report-level likelihood/reliability; a practical monitoring scenario if labels support one. Start with actual tested/implemented-only/deferred status: B90 observers/robust losses were NOT evaluated by the completed A/C/T pilot. For each give the competing explanation being tested, exact standard components and closest primary work, new scientific information over current experiments, minimum model equation and same-input/same-support/matched-compute controls, feasible data versus needed measurements, TRAIN/VAL decisions and reusedTEST limits, falsifier/inconclusive outcome, CPU/GPU requirement and bounded stop. Identify which source facts require retracting prior rankings. Return a ranked decision matrix and one best estimator-family hypothesis; do not demand new physics or algorithmic novelty as a prerequisite, but do not promise either. B104 already addresses budget. A few easy audits may be prerequisites, not the whole contribution. End with one program you reject and the strongest objection to your best candidate.''')],max_tokens=49152,effort='medium')
    challenge=D.call('10_adversarial_program_review',[D.textblock(D.CONTEXT),D.textblock('PRIMARY DOSSIERS\n'+json.dumps(reports)),D.textblock('SOURCE CROSSWALK\n'+crosswalk),D.textblock('CURRENT RESULTS\n'+json.dumps(evidence)),D.textblock('CANDIDATE PROGRAMS\n'+research),D.textblock('''Fresh adversarial research-design review, English<=1800words. Find actual errors, existing-work duplication, missing information, conditional-selection leakage and unfair compute. Proposals/earlier ranks are untrusted. Check source-time state update against B98 and B88, standard NLL versus faithful objective, current-anchor teacher information and TS2Vec causality. Give counterexamples and a corrected minimum comparison. Distinguish applicability from novelty/priority. Reject CI-overlap inference, failure-to-reject equivalence, arbitrary margins, physically identifying noise from F/L5, and treating different target supports as identical rows. Rank the3 most valuable programs and state what would cause each to be abandoned or promoted. Be candid if no model is justified, but don't dismiss deferred-and-unrun families as empirical failures. No acceptance estimates or execution.''')],max_tokens=32768,effort='medium')
    final=D.call('11_final_korean_decision',[D.textblock(D.CONTEXT),D.textblock('FOUR PRIMARY EVIDENCE DOSSIERS\n'+json.dumps(reports)),D.textblock('EXISTING WORK\n'+crosswalk),D.textblock('PROGRAMS\n'+research),D.textblock('FRESH CHALLENGE\n'+challenge),D.textblock('''Korean final actionable research memo<=2200words. Explicitly answer what the author should investigate NEXT and which method/scenario families are worth pursuing after thorough primary-paper/code reading, rather than only audits/limitations. State3-5 new findings and corrections versus the previous survey,5 scientific objectives, exactly3 priority bounded programs plus2 deferred options. For each program: hypothesis, closest prior paper/code locator and what is standard, real difference from B73-104 work, minimum implementation/equation, data/input/target/causal contract, correct same-support/same-budget controls, TRAIN/VAL decisions, exploratory reusedTEST and eventual independent confirmation, paired estimand/decision direction with margins only as proposed to preregister, positive/negative/inconclusive outcomes, resource uncertainty and stopping rule. Pick one recommended estimator family with conditions and a no-go result; compare it to a simpler model and retain adverse evidence. Do not assume data unavailable is impossible to obtain. Separate an actionable current-data predictive research path from physical claims requiring extra measurements. Provide primary citations as URLs plus exact locator, no invented timing/performance/novelty/acceptance. Include one immediate feasible step, no execution. Note source-access limitations and source-audit incomplete attempts honestly, but use completed narrow followups as evidence. Budget amount is not a reason to add experiments.''')],max_tokens=49152,effort='medium')
    D.E.gate()
    with D.LOCK:cost=D.ledger()
    D.save(D.OUT/'status.json',{'complete':True,'final_report':'11_final_korean_decision.md','budget_cap_usd':D.CAP,'estimated_list_price_usd':cost['estimated_spent_usd'],'paid_calls':len(cost['calls']),'incomplete_original_attempts':[v['stage'] for v in cost['calls'] if v.get('stop_reason') not in ['end_turn',None]],'scientific_fits_started':0,'gpu_runs_started':0,'test_informed_exploratory':True,'independent_confirmation_required':True})
    print('DEEP RESEARCH COMPLETE USD',cost['estimated_spent_usd'],flush=True)

if __name__=='__main__':main()
